    RAISE EXCEPTION 'Stop: Apply verified full Rajmoti schema before importing public photos.';
  END IF;
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = 'public.images'::regclass) THEN
    RAISE EXCEPTION 'Stop: public.images does not have Row Level Security enabled.';
  END IF;
END $check$;

