DO $validate$
BEGIN
  IF (SELECT count(*) FROM _rajmoti_catalogue) <> 385
    OR (SELECT count(distinct photo->>'id') FROM _rajmoti_catalogue) <> 385 THEN
    RAISE EXCEPTION 'Unexpected public photography manifest count or duplicate IDs.';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM _rajmoti_catalogue p JOIN public.images i
      ON i.short_id = p.photo->>'id'
    WHERE i.image_url IS DISTINCT FROM p.photo->'variants'->'large'->>'url'
  ) THEN
    RAISE EXCEPTION 'Existing photo short_id points to another photo; refusing to overwrite or duplicate it.';
  END IF;
END $validate$;

-- Insert missing taxonomy only. Never overwrite owner-managed names/covers.
INSERT INTO public.categories (slug, name, cover_image_url, display_order)
SELECT category->>'slug', category->>'name', category->>'cover', row_number() OVER (ORDER BY category->>'slug')::int
FROM _rajmoti_taxonomy t
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.subcategories (category_id, slug, name, cover_image_url, display_order)
SELECT c.id, sub.obj->>'slug', sub.obj->>'name', sub.obj->>'cover', sub.ord::int
FROM _rajmoti_taxonomy t
JOIN public.categories c ON c.slug = t.category->>'slug'
CROSS JOIN LATERAL jsonb_array_elements(t.category->'subcategories')
  WITH ORDINALITY AS sub(obj, ord)
ON CONFLICT (category_id, slug) DO NOTHING;

-- Keep existing taxonomy settings; fill empty cover images only.
UPDATE public.categories c
SET cover_image_url = t.category->>'cover'
FROM _rajmoti_taxonomy t
WHERE c.slug=t.category->>'slug'
  AND c.cover_image_url IS NULL;

UPDATE public.subcategories s
SET cover_image_url=sub.obj->>'cover'
FROM _rajmoti_taxonomy t
JOIN public.categories c ON c.slug=t.category->>'slug'
CROSS JOIN LATERAL jsonb_array_elements(t.category->'subcategories') AS sub(obj)
WHERE s.category_id=c.id AND s.slug=sub.obj->>'slug'
  AND s.cover_image_url IS NULL;

DO $check_taxonomy$
BEGIN
 IF (SELECT COUNT(*)
     FROM _rajmoti_catalogue p
     JOIN public.categories c ON c.slug=p.photo->>'category'
     JOIN public.subcategories s ON s.category_id=c.id AND s.slug=p.photo->>'subcategory'
 ) <> 385 THEN
    RAISE EXCEPTION 'Some published photos have unresolved category/subcategory mappings.';
 END IF;
END $check_taxonomy$;

-- Store catalog metadata only. Image files stay on the SAME public domain.
INSERT INTO public.images
  (short_id, title, alt_text, image_url, thumbnail_url,
   width, height, category_id, subcategory_id, variants, tags,
   display_order, hidden, featured)
SELECT
  p.photo->>'id',
  p.photo->>'title',
  p.photo->>'alt',
  p.photo->'variants'->'large'->>'url',
  p.photo->'variants'->'thumbnail'->>'url',
  (p.photo->'variants'->'large'->>'width')::integer,
  (p.photo->'variants'->'large'->>'height')::integer,
  c.id, s.id,
  p.photo->'variants',
  ARRAY(SELECT jsonb_array_elements_text(p.photo->'tags')),
  p.position, false, false
FROM _rajmoti_catalogue p
JOIN public.categories c ON c.slug = p.photo->>'category'
JOIN public.subcategories s ON s.category_id=c.id AND s.slug=p.photo->>'subcategory'
ON CONFLICT (short_id) DO NOTHING;

DO $verify$
BEGIN
 IF (SELECT count(*)
     FROM _rajmoti_catalogue p
     JOIN public.images i ON i.short_id = p.photo->>'id'
     WHERE i.image_url = p.photo->'variants'->'large'->>'url'
 ) <> 385 THEN
   RAISE EXCEPTION 'Not all approved public photographs are present with matching URLs.';
 END IF;
END $verify$;

NOTIFY pgrst, 'reload schema';
COMMIT;

